const math = require('mathjs');

const generate = () => {
    const m = 5; // mass in kg
    const g = 9.81; // acceleration due to gravity in m/s^2
    const r = 2; // radius in meters

    // Initial tension when theta = 0
    const tensionInitial = m * g; // T = mg

    // For theta = 45 degrees
    const theta = math.unit(45, 'degrees');
    const sinTheta = math.sin(theta);
    const cosTheta = math.cos(theta);

    // Velocity at theta = 45 degrees derived from energy conservation
    const v = math.sqrt(2 * g * r * (1 - cosTheta));

    // Tension calculation at theta = 45 degrees
    const tension45 = m * g * sinTheta + (m * math.square(v) / r);

    // Prepare the output data
    let svgString = `<svg
    xmlns="http://www.w3.org/2000/svg"
    xmlns:xlink="http://www.w3.org/1999/xlink"
    width="400" height="400">
    <circle cx="0" cy="0" r="4" style="fill: lightgrey" />
    <text x="-15" y="0" style="font: 11px sans-serif">Bob</text>
    <line x1="0" y1="0" x2="${r*math.cos(theta)}" y2="-${r*math.sin(theta)}" style="stroke: red; stroke-width: 2;" />
    <text x="${r*math.cos(theta) - 10}" y="-${r*math.sin(theta) + 10}" style="font: 11px sans-serif">Tension</text>
    <text x="0" y="15" style="font: 11px sans-serif">Tension at \(\theta = 0\): ${math.format(tensionInitial, {notation: 'fixed', precision: 3})} N</text>
    <text x="0" y="30" style="font: 11px sans-serif">Tension at \(\theta = 45^\circ\): ${math.format(tension45, {notation: 'fixed', precision: 3})} N</text>
    </svg>`;

    const data = {
        params: { 
            mass: m,
            theta: math.format(theta.toNumber('degrees'), {notation: 'fixed', precision: 2}),
            svgString: svgString
        },
        correct_answers: {
            initial_tension: tensionInitial,
            tension_45: tension45
        },
        nDigits: 3,
        sigfigs: 3
    }
    return data;
}

module.exports = {
    generate
};

const math = require('mathjs');
const generate = () => {
    const g = 9.81; // gravitational acceleration in m/s^2
    const r = math.randomInt(1, 10); // random radius between 1 and 10
    const m = math.randomInt(1, 5); // random mass between 1 and 5 kg
    const v = math.randomInt(1, 10); // random speed between 1 and 10 m/s
    const theta = math.randomInt(10, 45); // random angle between 10 and 45 degrees

    // Convert theta to radians for computation
    const thetaRad = math.unit(theta, 'deg').toNumber('rad');

    // Compute Tension T
    const T = (m * (v ** 2) / r + m * g * math.sin(thetaRad)) / math.cos(thetaRad);

    // Compute Normal Reaction N
    const N = m * g - T * math.sin(thetaRad) / math.cos(thetaRad);

    // Prepare result data structure
    const data = {
        params: {
            mass: m,
            gravity: g,
            speed: v,
            radius: r,
            angle: theta,
        },
        correct_answers: {
            tension: T,
            normal_reaction: N,
        },
        nDigits: 3,
        sigfigs: 3
    };

    console.log(data); // Output the computed data for debugging
    return data;
}

generate();
module.exports = {
    generate
};

