const math = require('mathjs');

const generate = () => {
    const r_c = 0.4; // ft
    const m = 0.5; // lb -> converting to weight (assuming g = 32.2 ft/s^2, so m= W/g)
    const g = 32.2; // ft/s^2
    const w = m; // weight in lb (note: w = mg where g is accounted for)

    const theta = math.unit(30, 'degrees').toNumber('radians'); // convert degrees to radians
    const dotTheta = 0.4; // rad/s
    const ddotTheta = 0.8; // rad/s^2

    const r = 2 * r_c * math.cos(theta);
    const dotR = -2 * r_c * math.sin(theta) * dotTheta;
    const ddotR = -2 * r_c * (math.cos(theta) * Math.pow(dotTheta, 2) + math.sin(theta) * ddotTheta);

    // Accelerations
    const a_r = ddotR - r * Math.pow(dotTheta, 2);
    const a_theta = r * ddotTheta + 2 * dotR * dotTheta;

    // Equations of motion
    const normalForce = (w * math.sin(theta) + m * a_r) / math.cos(theta);
    const F_OA = (m * a_theta - normalForce * math.sin(theta) + w * math.cos(theta));

    // Solution returns
    const data = {
        params: {
            w: w,
            r_c: r_c,
            theta: 30,
            unitsForce: 'lb',
            unitsDist: 'ft'
        },
        correct_answers: {
            normalForce: normalForce.toFixed(3),
            F_OA: F_OA.toFixed(3)
        },
        nDigits: 3,
        sigfigs: 3
    };

    console.log(data);
    return data;
};

generate();
module.exports = {
    generate
};

const math = require('mathjs');

const generate = () => {
    // Function to dynamically select parameters and generate problem values.
    const r_c = 1; // Example constant value for r_c, can be adjusted based on problem context.
    const theta = Math.random() * (Math.PI); // Generate random angle theta in the range [0, pi].
    const theta_dot = Math.random() * (2); // Generate random angular velocity in range [0, 2]
    const theta_ddot = Math.random() * (1); // Generate random angular acceleration in range [0, 1]

    // Calculate the time derivatives of r.
    const r = 2 * r_c * Math.cos(theta);
    const r_dot = -2 * r_c * Math.sin(theta) * theta_dot;  // First derivative
    const r_ddot = -2 * r_c * Math.cos(theta) * Math.pow(theta_dot, 2) 
                  - 2 * r_c * Math.sin(theta) * theta_ddot; // Second derivative

    return {
        params: {
            r, // Value of r
            theta, // Value of theta
            theta_dot, // First derivative of theta
            theta_ddot // Second derivative of theta
        },
        correct_answers: {
            r_dot, // Value of r_dot
            r_ddot // Value of r_ddot
        },
        nDigits: 3,  // Decimal places.
        sigfigs: 3   // Significant figures.
    };
}

module.exports = { generate };

